import React,{useState,useEffect} from 'react';
import {Link,useLocation,useHistory} from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import {useAuth} from '../auth';
import {postsRequest} from './api';
import './style.css';
export default function Editor(){const {user,accessToken}=useAuth(),location=useLocation(),history=useHistory();const id=new URLSearchParams(location.search).get('id');
 const [form,setForm]=useState({title:'',summary:'',body:'',category:'后端',goal:'项目实战',practice:0}),[error,setError]=useState(''),[busy,setBusy]=useState(false),[loading,setLoading]=useState(!!id),[allowed,setAllowed]=useState(!id);
 useEffect(()=>{let live=true;if(!id)return;setLoading(true);setAllowed(false);postsRequest('?id=eq.'+encodeURIComponent(id)).then(rows=>{if(!live)return;if(!rows[0]||rows[0].author_id!==user.id)throw new Error('文章不存在，或你没有编辑权限');const r=rows[0];setForm({title:r.title,summary:r.summary,body:r.body,category:r.category,goal:r.goal,practice:r.practice});setAllowed(true);}).catch(e=>{if(live)setError(e.message);}).finally(()=>{if(live)setLoading(false);});return()=>{live=false;};},[id,user.id]);
 const change=e=>setForm({...form,[e.target.name]:e.target.value});
 const submit=async e=>{e.preventDefault();if(busy||!allowed)return;setError('');if(form.title.trim().length<2||form.body.trim().length<20){setError('标题至少 2 个字，正文至少 20 个字');return;}setBusy(true);try{const body={...form,title:form.title.trim(),summary:form.summary.trim()||form.body.trim().slice(0,160),body:form.body.trim(),practice:Number(form.practice),...(!id?{author_id:user.id,author_name:user.user_metadata.nickname||'读者'}:{})};const rows=await postsRequest(id?'?id=eq.'+encodeURIComponent(id):'',id?'PATCH':'POST',body,accessToken);if(!rows.length)throw new Error('保存未成功，请刷新登录状态后再试');history.push('/detail/'+rows[0].id);}catch(e){setError(e.message);}finally{setBusy(false);}};
 return <main className="post-editor"><Link to="/">← 返回首页</Link><h1>{id?'编辑文章':'写一篇新文章'}</h1><p>分享你的实践和思考，发布后所有访客都能阅读。</p>{error&&<p role="alert" className="auth-error">{error}</p>}{loading?<p>正在读取文章…</p>:<form onSubmit={submit}><label>文章标题<input name="title" value={form.title} onChange={change} required minLength={2} maxLength={120}/></label><label>摘要<input name="summary" value={form.summary} onChange={change} maxLength={300} placeholder="一句话介绍你的文章"/></label><div className="post-fields"><label>分类<select name="category" value={form.category} onChange={change}>{['前端','后端','开发工具'].map(x=><option key={x}>{x}</option>)}</select></label><label>阅读目标<select name="goal" value={form.goal} onChange={change}>{['解决问题','学习原理','准备面试','项目实战'].map(x=><option key={x}>{x}</option>)}</select></label><label>建议练习（分钟）<input name="practice" type="number" min="0" max="120" value={form.practice} onChange={change}/></label></div><div className="post-columns"><label>正文（支持 Markdown）<textarea name="body" value={form.body} onChange={change} required minLength={20} maxLength={100000}/></label><section className="read-prose"><h2>预览</h2><ReactMarkdown source={form.body}/></section></div><button className="detail-primary" disabled={busy||!allowed}>{busy?'正在保存…':id?'保存修改':'发布文章'}</button></form>}</main>;
}
export function PostControls({article}){const {user,accessToken}=useAuth(),history=useHistory();const [busy,setBusy]=useState(false),[error,setError]=useState('');if(!user||user.id!==article.author_id)return null;
 const remove=async()=>{if(!window.confirm('确定删除这篇文章？删除后无法恢复。'))return;setBusy(true);setError('');try{const rows=await postsRequest('?id=eq.'+encodeURIComponent(article.id),'DELETE',null,accessToken);if(!rows.length)throw new Error('文章未删除，请刷新后重试');history.push('/');}catch(e){setError(e.message);setBusy(false);}};
 return <div className="post-controls"><Link to={'/write?id='+article.id}>编辑文章</Link><button disabled={busy} onClick={remove}>{busy?'删除中…':'删除文章'}</button>{error&&<p role="alert">{error}</p>}</div>;
}
