import React,{createContext,useContext,useEffect,useState} from 'react';
import {Link,useLocation,useHistory,Redirect} from 'react-router-dom';
import './style.css';
const URL=(process.env.REACT_APP_SUPABASE_URL||'').replace(/\/$/,'');
const KEY=process.env.REACT_APP_SUPABASE_ANON_KEY||'';
export const configured=!!(URL&&KEY);
const Auth=createContext(null), storageKey='shifen:auth';
function read(){try{return JSON.parse(localStorage.getItem(storageKey)||'null');}catch{return null;}}
async function request(path,body,token,method='POST'){
 if(!configured)throw new Error('账号服务尚未开通，请稍后再试。');
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
 try{const r=await fetch(URL+'/auth/v1/'+path,{method,headers:{apikey:KEY,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:controller.signal});const data=await r.json().catch(()=>({}));if(!r.ok){const code=data.code||data.error_code;const messages={invalid_credentials:'邮箱或密码不正确',email_not_confirmed:'请先完成邮箱验证，再登录',user_already_exists:'该邮箱已注册，请直接登录',over_email_send_rate_limit:'邮件发送过于频繁，请稍后重试',weak_password:'密码强度不足，请使用更长的密码',signup_disabled:'当前暂未开放注册'};throw new Error(messages[code]||(r.status===429?'操作过于频繁，请稍后再试':'认证未成功，请检查信息后重试。'));}return data;}catch(e){if(e.name==='AbortError')throw new Error('请求超时，请稍后重试');if(e instanceof TypeError)throw new Error('无法连接账号服务，请检查网络后重试');throw e;}finally{clearTimeout(timer);}}
export function AuthProvider({children}){const [session,setSession]=useState(null),[ready,setReady]=useState(false);const persist=s=>{setSession(s);try{if(s)localStorage.setItem(storageKey,JSON.stringify(s));else localStorage.removeItem(storageKey);}catch{}};
 useEffect(()=>{let live=true;async function restore(){const old=read();if(!configured||!old){if(live)setReady(true);return;}try{let next=old;if(!old.expires_at||old.expires_at*1000<Date.now()+60000){next=await request('token?grant_type=refresh_token',{refresh_token:old.refresh_token});next.expires_at=next.expires_at||Math.floor(Date.now()/1000)+next.expires_in;}const user=await request('user',null,next.access_token,'GET');if(live)persist({...next,user});}catch{if(live)persist(null);}finally{if(live)setReady(true);}}restore();const sync=()=>{setReady(false);restore();};window.addEventListener('storage',sync);return()=>{live=false;window.removeEventListener('storage',sync);};},[]);
 useEffect(()=>{if(!session)return;const timer=setTimeout(async()=>{try{const next=await request('token?grant_type=refresh_token',{refresh_token:session.refresh_token});persist({...next,expires_at:next.expires_at||Math.floor(Date.now()/1000)+next.expires_in});}catch{persist(null);}},Math.max(1000,(session.expires_at*1000-Date.now()-60000)));return()=>clearTimeout(timer);},[session]);
 const login=async(email,password)=>{const s=await request('token?grant_type=password',{email,password});persist({...s,expires_at:s.expires_at||Math.floor(Date.now()/1000)+s.expires_in});};
 const register=async(email,password,nickname)=>{const s=await request('signup',{email,password,data:{nickname}});if(s.access_token){persist({...s,expires_at:s.expires_at||Math.floor(Date.now()/1000)+s.expires_in});return true;}return false;};
 const logout=async()=>{try{if(session)await request('logout',null,session.access_token);}finally{persist(null);}};
 return <Auth.Provider value={{user:session&&session.user,accessToken:session&&session.access_token,ready,login,register,logout}}>{children}</Auth.Provider>;}
export const useAuth=()=>useContext(Auth);
export function AuthNav(){const {user,ready,logout}=useAuth();const [error,setError]=useState('');if(!ready)return <span className="auth-nav-loading">加载中…</span>;return user?<details className="auth-menu"><summary><span>{(user.user_metadata.nickname||user.email||'我')[0]}</span>{user.user_metadata.nickname||'读者'}</summary><div><small>{user.email}</small><Link to="/account">我的账号</Link><button onClick={()=>logout().catch(()=>setError('已退出本机，服务器会话撤销失败，请稍后重试。'))}>退出登录</button>{error&&<small role="alert">{error}</small>}</div></details>:<Link className="auth-nav-link" to="/login">登录 / 注册</Link>;}
export function RequireAuth({children}){const {user,ready}=useAuth();const location=useLocation();if(!ready)return <p className="auth-loading">正在恢复登录状态…</p>;return user?children:<Redirect to={{pathname:'/login',state:{from:location.pathname}}}/>;}
export function AuthPage(){const location=useLocation(),history=useHistory(),{user,login,register}=useAuth();const registering=location.pathname==='/register';const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[nickname,setNickname]=useState(''),[visible,setVisible]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');const from=location.state&&location.state.from;const destination=from&&from.startsWith('/')&&!from.startsWith('//')&&!['/login','/register'].includes(from)?from:'/';
 useEffect(()=>{setError('');setNotice('');setPassword('');setConfirm('');},[registering]);
 if(user)return <Redirect to={destination}/>;
 const submit=async e=>{e.preventDefault();if(busy)return;setError('');setNotice('');if(registering&&password!==confirm){setError('两次输入的密码不一致');return;}setBusy(true);try{if(registering){const signedIn=await register(email.trim(),password,nickname.trim());if(signedIn)history.replace(destination);else{setNotice('请查收验证邮件，验证完成后返回此处登录。若邮箱已注册，可直接登录。');setPassword('');setConfirm('');}}else{await login(email.trim(),password);history.replace(destination);}}catch(e){setError(e.message);}finally{setBusy(false);}};
 return <main className="auth-page"><section className="auth-story"><span>SHIFEN / 拾分</span><h1>每一点积累，<br/>都在让你向前。</h1><p>发现值得读的内容，<br/>留下属于自己的思考。</p><div className="auth-art"><b>拾</b><i>READ · THINK · GROW</i></div><Link to="/">← 先去看看文章</Link></section><section className="auth-panel"><div className="auth-tabs"><Link className={!registering?'selected':''} to={{pathname:'/login',state:location.state}}>登录</Link><Link className={registering?'selected':''} to={{pathname:'/register',state:location.state}}>注册</Link></div>{registering&&notice?<section className="auth-verification" role="status"><h2>下一步：验证邮箱</h2><p>注册请求已提交，请查看 <strong>{email}</strong> 的收件箱和垃圾邮件。</p><p>点击邮件中的验证链接后，使用刚才设置的密码登录。密码框清空不代表密码丢失。</p><p>如果这个邮箱已经注册，请直接登录。</p><Link className="auth-submit" style={{display:'block',textAlign:'center',boxSizing:'border-box',textDecoration:'none'}} to={{pathname:'/login',state:location.state}}>我已验证，前往登录</Link><button type="button" style={{marginTop:20}} onClick={()=>{setNotice('');setVisible(false);}}>邮箱填错了？返回修改</button></section>:<><h2>{registering?'开始你的阅读旅程':'欢迎回来'}</h2><p>{registering?'创建账号，让每次阅读都有新的开始。':'登录拾分，继续你的探索。'}</p><form onSubmit={submit}>{registering&&<label>昵称<input required minLength={2} maxLength={20} autoComplete="nickname" value={nickname} onChange={e=>setNickname(e.target.value)} placeholder="给自己起个名字"/></label>}<label>邮箱<input required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>密码<div className="auth-password"><input required minLength={registering?8:1} maxLength={128} type={visible?'text':'password'} autoComplete={registering?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder={registering?'至少 8 位字符':'输入密码'}/><button type="button" aria-label={visible?'隐藏密码':'显示密码'} onClick={()=>setVisible(!visible)}>{visible?'隐藏':'显示'}</button></div></label>{registering&&<label>确认密码<input required type={visible?'text':'password'} autoComplete="new-password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="再次输入密码"/></label>}{error&&<div className="auth-error" role="alert">{error}</div>}{notice&&<div className="auth-notice" role="status">{notice}</div>}<button className="auth-submit" disabled={busy} type="submit">{busy?'正在处理…':registering?'创建账号':'登录'}</button></form><p className="auth-bottom">{registering?'已有账号？':'还没有账号？'} <Link to={registering?'/login':'/register'}>{registering?'立即登录':'立即注册'} →</Link></p></>}</section></main>;}
export function AccountPage(){const {user}=useAuth();return <main className="auth-account"><h1>我的账号</h1><p>昵称：{user.user_metadata.nickname||'读者'}</p><p>邮箱：{user.email}</p><Link to="/">返回发现 →</Link></main>;}
