import React, { useState, useEffect } from 'react';
import { Link, useParams, useLocation, useHistory } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import seedArticles from './articles.json';
import {usePosts,postsRequest,asArticle} from '../posts/api';
import {PostControls} from '../posts/Editor';
import './style.css';
import {AuthNav} from '../auth';
import { renderers as codeRenderers } from '../common/markdown/renderers';
function readFollowing(){try{const list=JSON.parse(localStorage.getItem('shifen:following')||'[]');return Array.isArray(list)?list.filter(x=>typeof x==='string'):[];}catch{return [];}}
function useFollowing(){const [following,setFollowing]=useState(readFollowing);useEffect(()=>{const sync=()=>setFollowing(readFollowing());window.addEventListener('storage',sync);window.addEventListener('shifen-follow',sync);return()=>{window.removeEventListener('storage',sync);window.removeEventListener('shifen-follow',sync);};},[]);const toggle=author=>{const next=following.includes(author)?following.filter(x=>x!==author):[...following,author];try{localStorage.setItem('shifen:following',JSON.stringify(next));window.dispatchEvent(new Event('shifen-follow'));return true;}catch{return false;}};return [following,toggle];}
export function ReadingHeader(){const history=useHistory(),location=useLocation();const [search,setSearch]=useState('');return <header className="read-header"><div className="header-inner"><Link className="read-brand" to="/"><b>拾</b> 拾分<span>技术阅读</span></Link><nav className="header-channels" aria-label="主导航"><Link className={location.pathname==='/'?'selected':''} to="/">首页</Link><Link to="/?mode=short">短读精选</Link><Link to="/?goal=项目实战">实战文章</Link></nav><form className="header-search" onSubmit={e=>{e.preventDefault();history.push('/?q='+encodeURIComponent(search.trim()));}}><input aria-label="搜索拾分" placeholder="搜索文章、技术与灵感" value={search} onChange={e=>setSearch(e.target.value)}/><button aria-label="提交搜索" type="submit"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg></button></form><nav className="header-account"><Link className="header-create" to="/write">＋ 写文章</Link><AuthNav/></nav></div></header>}
export function filterArticles(list, {budget,goal,category,query}) { return list.filter(a=>(!budget || a.minutes+a.practice<=budget) && (goal==='全部目标'||a.goal===goal) && (category==='全部'||a.category===category) && (a.title+a.summary+a.category+a.goal).toLowerCase().includes(query.trim().toLowerCase())); }
function Chips({values,value,onChange,label}){return <div className="read-chips" role="group" aria-label={label}>{values.map(v=><button key={v} aria-pressed={v===value} className={v===value?'active':''} onClick={()=>onChange(v)}>{v}</button>)}</div>}
export function ReadingHome(){
 const cloud=usePosts();const articles=[...cloud.rows,...seedArticles];
 const [following]=useFollowing();
 useEffect(()=>{window.scrollTo(0,0);},[]);
 const location=useLocation(); const params=new URLSearchParams(location.search);
 const [budget,setBudget]=useState(Number(params.get('time'))||0),[goal,setGoal]=useState(params.get('goal')||'全部目标'),[category,setCategory]=useState('全部'),[query,setQuery]=useState(''),[sort,setSort]=useState('recommended');
 useEffect(()=>{const p=new URLSearchParams(location.search);setQuery(p.get('q')||'');setGoal(p.get('goal')||'全部目标');setBudget(Number(p.get('time'))||0);setCategory('全部');setSort(p.get('mode')==='short'?'short':'recommended');},[location.search]);
 const results=filterArticles(articles,{budget,goal,category,query}).filter(a=>sort!=='following'||following.includes(a.author)).sort((a,b)=>sort==='short'?a.minutes+a.practice-b.minutes-b.practice:sort==='new'?b.date.localeCompare(a.date):String(b.date).localeCompare(String(a.date)));
 const reset=()=>{setBudget(0);setGoal('全部目标');setCategory('全部');setQuery('');setSort('recommended');};
 return <main className="read-shell community-shell"><aside className="community-left"><h2>探索社区</h2><nav aria-label="频道分类">{['全部','前端','后端','开发工具'].map((v,i)=><button key={v} className={category===v?'active':''} aria-pressed={category===v} onClick={()=>setCategory(v)}><span>{['◈','⌘','▤','⚒'][i]}</span>{v==='全部'?'综合推荐':v}<small>{articles.filter(a=>v==='全部'||a.category===v).length}</small></button>)}</nav><div className="community-left-bottom"><span>每天一点，积少成多</span><p>为好奇心留一点时间。</p><Link to="/?mode=short">发现短读 →</Link></div></aside><div className="community-center"><section className="community-welcome"><div><span>YOUR DAILY INSPIRATION</span><h1>发现好内容，让阅读有收获。</h1></div><b>拾分 · 每日精选</b></section>
 <section className="read-planner"><div className="read-section-title"><h2>今天，你有多少时间？</h2><span>预计阅读 + 建议练习时间</span></div><Chips label="可用时间" values={['不限时间','5 分钟','15 分钟','30 分钟']} value={budget?budget+' 分钟':'不限时间'} onChange={v=>setBudget(parseInt(v,10)||0)}/><div className="read-goals"><span>我想</span><Chips label="阅读目标" values={['全部目标','解决问题','学习原理','准备面试','项目实战']} value={goal} onChange={setGoal}/></div></section>
 <section className="read-feed">{cloud.loading&&<p className="cloud-status">正在读取社区文章…</p>}{cloud.error&&<p className="cloud-status" role="alert">{cloud.error}，以下仍可阅读精选文章。<button onClick={cloud.retry}>重试</button></p>}<div className="read-toolbar"><Chips label="文章推荐顺序" values={['推荐','最新','关注','短读']} value={{recommended:'推荐',new:'最新',following:'关注',short:'短读'}[sort]} onChange={v=>setSort({'推荐':'recommended','最新':'new','关注':'following','短读':'short'}[v])}/><span className="feed-channel">{category==='全部'?'综合推荐':category}{query?' · 搜索：'+query:''}</span></div><div className="read-result"><span>为你找到 <b>{results.length}</b> 篇文章</span><select aria-label="文章排序" value={sort} onChange={e=>setSort(e.target.value)}><option value="recommended">精选顺序</option><option value="new">最新发布</option><option value="short">用时最短</option><option value="following">已关注作者</option></select></div>
 {results.map(a=><article className="read-card" key={a.id}><div className="read-meta"><span className="read-avatar">{a.author[0]}</span>{a.author}<span>· {a.date} · {a.category}</span></div><Link to={'/detail/'+a.id}><h2>{a.title}</h2><p>{a.summary}</p></Link><div className="read-card-bottom"><span className="read-tag">{a.goal}</span><span>{a.level} · 阅读约 {a.minutes} 分钟 + 练习 {a.practice} 分钟</span><Link to={'/detail/'+a.id} aria-label={'阅读：'+a.title}>去阅读 ↗</Link></div></article>)}
 {!results.length&&<div className="read-empty"><h2>{sort==='following'&&!following.length?'还没有关注作者':'暂时没有匹配的文章'}</h2><p>{sort==='following'&&!following.length?'打开喜欢的文章，点击作者旁的关注，即可在这里查看他的文章。':'试试增加可用时间，或换一个阅读目标。'}</p><button onClick={reset}>清空筛选</button></div>}</section>
 </div><aside className="read-aside"><div className="read-note"><span className="read-eyebrow">HOW IT WORKS</span><h2>不只是读完，<br/>更要有所收获。</h2><p>01 选择时间与目标</p><p>02 看懂文章的阅读收获卡</p><p>03 留一点时间，动手验证</p></div><div className="read-aside-card"><h3>本期编辑精选</h3><Link to="/detail/1">闭包不是魔法 →</Link><Link to="/detail/4">讲清 HTTP 缓存 →</Link><hr/><p>本站文章为演示学习内容。阅读时长按正文长度估算，练习时间仅供参考。</p></div></aside><footer className="read-footer">拾分 · 让碎片时间，也有完整收获。<span>每一次阅读，都有新的收获</span></footer></main>
}
export function ReadingDetail(){const {id}=useParams();const seed=seedArticles.find(x=>String(x.id)===id);const [state,setState]=useState({id:null,article:null,error:''});useEffect(()=>{let live=true;if(seed)return;postsRequest('?id=eq.'+encodeURIComponent(id)).then(rows=>{if(live)setState({id,article:rows[0]?asArticle(rows[0]):null,error:rows.length?'':'这篇文章不存在或已删除'});}).catch(e=>{if(live)setState({id,article:null,error:e.message});});return()=>{live=false;};},[id,seed]);const a=seed||(state.id===id&&state.article);return a?<DetailContent key={id} article={a}/>:<main className="read-shell read-empty"><h1>{state.id===id?state.error:'正在加载文章…'}</h1><Link to="/">返回文章列表 →</Link></main>;}
function loadRecord(id){try{const v=JSON.parse(localStorage.getItem('shifen:article:'+id)||'{}');return {liked:!!v.liked,saved:!!v.saved,comments:Array.isArray(v.comments)?v.comments.filter(c=>typeof c.text==='string'&&typeof c.date==='string'):[]};}catch{return {liked:false,saved:false,comments:[]};}}
function DetailContent({article:a}){
 const cloud=usePosts();const articles=[...cloud.rows,...seedArticles];
 const [following,toggleFollow]=useFollowing();
 const followed=following.includes(a.author);
 const follow=()=>setMessage(toggleFollow(a.author)?(followed?'已取消关注':'已关注，可在首页“关注”中查看作者文章'):'无法保存关注，请检查浏览器存储设置');
 const [record,setRecord]=useState(()=>loadRecord(a.id)),[draft,setDraft]=useState(''),[message,setMessage]=useState(''),[progress,setProgress]=useState(0),[active,setActive]=useState(0);
 const headings=a.body.split('\n').filter(l=>l.startsWith('## ')).map(l=>l.slice(3));
 useEffect(()=>{window.scrollTo(0,0);document.title=a.title+' · 拾分';const update=()=>{const body=document.getElementById('article-body');if(!body)return;const start=body.getBoundingClientRect().top+window.scrollY;const range=Math.max(1,body.offsetHeight-window.innerHeight+100);setProgress(Math.round(Math.min(100,Math.max(0,(window.scrollY-start+120)/range*100))));const nodes=body.querySelectorAll('h2');let current=0;nodes.forEach((n,i)=>{if(n.getBoundingClientRect().top<180)current=i;});setActive(current);};window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update();return()=>{window.removeEventListener('scroll',update);window.removeEventListener('resize',update);document.title='拾分 · 技术阅读';};},[a.title]);
 useEffect(()=>{if(!message)return;const timer=setTimeout(()=>setMessage(''),3200);return()=>clearTimeout(timer);},[message]);
 const save=next=>{setRecord(next);try{localStorage.setItem('shifen:article:'+a.id,JSON.stringify(next));setMessage('已保存到当前浏览器');}catch{setMessage('浏览器存储不可用，本次操作仅在当前页面生效');}};
 const jump=id=>{const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'});};
 const share=async()=>{try{await navigator.clipboard.writeText(window.location.href);setMessage('链接已复制；可以分享给其他读者');}catch{setMessage('复制失败，请从浏览器地址栏复制链接');}};
 const submit=e=>{e.preventDefault();if(!draft.trim())return;save({...record,comments:[...record.comments,{id:Date.now().toString(36),text:draft.trim(),date:new Date().toLocaleString('zh-CN')}]});setDraft('');};
 const recommended=articles.filter(x=>x.id!==a.id).sort((x,y)=>(Number(y.category===a.category)*2+Number(y.goal===a.goal))-(Number(x.category===a.category)*2+Number(x.goal===a.goal)));
 const related=articles.filter(x=>x.id!==a.id).sort((x,y)=>Number(y.category===a.category)-Number(x.category===a.category)).slice(0,3);
 return <main className="detail-layout"><div className="detail-progress" style={{width:progress+'%'}}/><nav className="detail-actions" aria-label="文章互动"><button className="rail-follow" aria-label={followed?'取消关注作者':'关注作者'} aria-pressed={followed} onClick={follow}><span>{a.author[0]}</span>{followed?'已关注':'＋关注'}</button><button aria-pressed={record.liked} onClick={()=>save({...record,liked:!record.liked})}><span>♡</span>{record.liked?'已点赞':'点赞'}</button><button onClick={()=>jump('discussion')}><span><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" aria-hidden="true"><path d="M4 4h16v12H9l-5 4z"/><path d="M8 8h8M8 12h5"/></svg></span>评论 {record.comments.length}</button><button aria-pressed={record.saved} onClick={()=>save({...record,saved:!record.saved})}><span>☆</span>{record.saved?'已收藏':'收藏'}</button><button onClick={share}><span>↗</span>分享</button><button onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}><span>↑</span>顶部</button></nav>
 <div className="detail-main"><Link className="read-back" to="/">← 返回文章列表</Link><article className="detail-paper"><div className="read-meta"><span className="read-tag">{a.goal}</span><span>{a.level}</span></div><h1>{a.title}</h1><PostControls article={a}/><div className="detail-byline"><span className="detail-avatar">{a.author[0]}</span><div><strong>{a.author}</strong><p>{a.date} · 预计阅读 {a.minutes} 分钟</p></div><button className="author-follow inline-follow" aria-pressed={followed} onClick={follow}>{followed?'已关注':'＋ 关注'}</button><span className="detail-topic">#{a.category}</span></div>
 <details className="read-outcomes" open><summary>✦ 阅读收获卡 <span>先看收获，再开始阅读</span></summary><dl><div><dt>解决什么问题</dt><dd>{a.summary}</dd></div><div><dt>需要什么基础</dt><dd>{a.prereq}</dd></div><div><dt>你将学会</dt><dd>{a.outcome}</dd></div></dl><p>建议安排：阅读约 {a.minutes} 分钟 + 动手练习 {a.practice} 分钟</p></details>
 <div id="article-body" className="read-prose"><ReactMarkdown source={a.body} renderers={{...codeRenderers,heading:({level,children})=>React.createElement('h'+level,{id:'section-'+headings.indexOf(children.map(c=>typeof c==='string'?c:c.props.children).join(''))},children)}}/></div>
 <div className="read-end"><span className="read-eyebrow">TURN READING INTO LEARNING</span><h3>读完了，把理解留在这里。</h3><p>用自己的话解释：{a.outcome}。</p><button className="detail-primary" onClick={()=>jump('comment-input')}>写下我的理解 ↓</button></div><p className="detail-disclaimer">示例学习内容 · 点赞、收藏和评论仅保存在当前浏览器。</p></article>
 <section className="detail-discussion" id="discussion"><h2>交流与思考 <span>{record.comments.length}</span></h2><form onSubmit={submit}><label htmlFor="comment-input">你的阅读收获</label><textarea id="comment-input" maxLength={1000} value={draft} onChange={e=>setDraft(e.target.value)} placeholder="分享一个收获，或提出你还没想明白的问题…"/><div className="detail-comment-footer"><span>{draft.length}/1000 · 本地评论演示</span><button className="detail-primary" disabled={!draft.trim()} type="submit">发表想法</button></div></form>{record.comments.length===0?<p className="detail-no-comments">还没有想法，来写下第一条阅读笔记。</p>:record.comments.map(c=><div className="detail-comment" key={c.id}><strong>我 <span>{c.date}</span></strong><p>{c.text}</p><button onClick={()=>save({...record,comments:record.comments.filter(x=>x.id!==c.id)})}>删除</button></div>)}</section><section className="detail-recommendations" aria-label="为你推荐"><div className="recommend-heading"><h2>为你推荐</h2><span>根据当前文章的分类与阅读目标推荐</span></div>{recommended.map(x=><article key={x.id}><Link to={'/detail/'+x.id}><h3>{x.title}</h3><p>{x.summary}</p></Link><div className="recommend-meta"><span>{x.author}</span><span>{x.date}</span><span>阅读约 {x.minutes} 分钟</span><span className="read-tag">{x.category}</span><span className="read-tag">{x.goal}</span></div></article>)}<Link className="recommend-more" to="/">发现更多文章 →</Link></section></div>
 <aside className="detail-sidebar"><section className="detail-author"><div className="detail-author-title"><span className="detail-avatar">{a.author[0]}</span><div><h2>{a.author}</h2><p>{a.category} · 技术分享者</p></div></div><p>把复杂的问题讲清楚，把学到的知识用起来。</p><div className="detail-author-stats"><strong>{articles.filter(x=>x.author===a.author).length}<span>本站文章</span></strong><strong>{a.category}<span>关注领域</span></strong></div><button className="author-follow" aria-pressed={followed} onClick={follow}>{followed?'已关注 · 点击取消':'＋ 关注作者'}</button></section><section className="detail-related"><h2>继续探索</h2>{related.map(x=><Link key={x.id} to={'/detail/'+x.id}><h3>{x.title}</h3><p>{x.author} · {x.goal} · 阅读约 {x.minutes} 分钟</p></Link>)}</section><section className="detail-toc"><div><h2>文章目录</h2><span>{progress}%</span></div><progress max="100" value={progress} aria-label="阅读进度"/>{headings.map((h,i)=><button className={active===i?'active':''} key={h} onClick={()=>jump('section-'+i)}>{String(i+1).padStart(2,'0')}　{h}</button>)}</section></aside><div className="detail-status" role="status">{message}</div></main>;
}
